public class Pb {


	public static void main(String[] args) throws NumberFormatException, IOException {


	Scanner s = new Scanner(System.in);
	BufferedReader br= new BufferedReader (new InputStreamReader(System.in));
	ArrayList<String > arr = new ArrayList<>();
	ArrayList<Integer > ar = new ArrayList<>();
	int tam = Integer.parseInt(br.readLine());
	String cad= br.readLine();
	String word ="";


	int cont = 0, mayor=0;
	boolean flg= false;


	for (int i = 0; i < tam; i++) {

		if(cad.charAt(i)=='('){			
			if (cont >= mayor){
				mayor=cont;
				cont=0;
			}
			cont=0;
			flg=true;
			continue;
		}

		if(cad.charAt(i)==')' ){			
			flg=false;	
			if(word!=""){
				arr.add(word);
				word= "";
			}
			continue;

		}
		else if(flg==true && cad.charAt(i)!='_'){
			word+=cad.charAt(i);
			continue;

		}

		else if(flg== true && cad.charAt(i)=='_' && word!=""){
			arr.add(word);
			word="";	
			continue;
		}


		else if(flg == false && cad.charAt(i)!='_'){
			cont++;
			if(i==(tam-1) && cont>= mayor){
				mayor=cont;				
			}
			continue;

		}
		else if ( flg==false && cad.charAt(i)=='_'){
			if (cont >= mayor){
				mayor=cont;
				cont=0;
			}
			cont=0;
		}

	}
	//System.out.println(arr);

	System.out.println(mayor + " "+ arr.size());


	}

}

